def read_ints():
    return list(map(int, input().split()))

n, m = read_ints()
edges = []
for _ in range(m):
    u, v, c = input().split()
    u, v = int(u), int(v)
    edges.append((u, v, c))

# Check if all edges can be made the same color
def is_possible_to_make_same_color(edges):
    color_count = {'R': 0, 'B': 0}
    for u, v, c in edges:
        color_count[c] += 1
    return color_count['R'] % 2 == color_count['B'] % 2

# If it's not possible to make all edges the same color, return -1
if not is_possible_to_make_same_color(edges):
    print(-1)
else:
    # Find the minimum number of moves required
    moves = []
    for i in range(n):
        if (edges[i][2] == 'R' and i % 2 == 0) or (edges[i][2] == 'B' and i % 2 == 1):
            moves.append(edges[i][0])
        else:
            moves.append(edges[i][1])
    print(len(moves))
    print(' '.join(map(str, moves)))
